def allruns():
  out=[];k=0;N=len(cy)
  while k<N-1:
    if cy[k]['ch31']==0 and cy[k+1]['ch31']==1 and cy[k]['ch16'] and not cy[k]['ch26']:
      s=k+1;e=s
      while e<N-1 and cy[e]['ch31']==1 and not cy[e]['ch26']: e+=1
      out.append((s,e)); k=e   # rows s..e-1 are executed instructions observed at t+1
    else: k+=1
  return out
def solve(s,e,branchops=('110',)):
  T=list(range(s,e))
  mems=[mem_at(t) for t in T]
  # forward sets
  fw=[{0}]
  trans=[]
  for idx,t in enumerate(T):
    M=mems[idx];nxt=set();tr={}
    for pc in fw[-1]:
      w=M[pc]
      p=cy[t+1]['ch25'];r=cy[t+1]['ch31']
      o=op(w) if w else None
      if o is not None:
        if p!=(o=='001'): continue
        if r!=(o!='111'): continue
      if not r: tr[pc]=set(); continue
      cand={(pc+1)%16}
      if o is None or o in branchops: cand=set(range(16))
      tr[pc]=cand; nxt|=cand
    trans.append(tr); fw.append(nxt)
  # backward
  ok=[None]*len(T)
  good=set(range(16)) if cy[e]['ch31'] or cy[e-1]['ch26'] else None
  # last step: states in trans[-1] valid
  valid=set(trans[-1].keys()) if trans else set()
