from pcs import *
def fb(s,e,BR=('101','110'),targets=None):
  T=list(range(s,e)); mems=[mem_at(t) for t in T]
  fw=[{0}]; edges=[]
  for i,t in enumerate(T):
    M=mems[i]; nxt=set(); ed=set()
    p=cy[t+1]['ch25'];r=cy[t+1]['ch31']
    for pc in fw[-1]:
      w=M[pc] or '0'*16; o=op(w)
      if p!=(o=='001') or r!=(o!='111'): continue
      if not r: ed.add((pc,None)); continue
      if o in BR:
        c=set(range(16)) if targets is None else targets(w,pc)
      else: c={(pc+1)%16}
      for n in c: ed.add((pc,n)); nxt.add(n)
    edges.append(ed); fw.append(nxt)
  # backward
  alive=[None]*(len(T)+1)
  alive[len(T)]=fw[len(T)] | ({None})
  for i in range(len(T)-1,-1,-1):
    edges[i]={(a,b) for (a,b) in edges[i] if b in alive[i+1] or b is None}
    alive[i]={a for a,b in edges[i]}
  return T,mems,edges
