import sys
sys.setrecursionlimit(10000)
def solve_run(s,e,kind,limit=200000):
  """kind: dict op->'u'|'c'. returns list of solutions (target maps) """
  T=list(range(s,e)); mems=[mem_at(t) for t in T]
  sols=[];cnt=[0]
  def rec(i,pc,tmap):
    cnt[0]+=1
    if cnt[0]>limit: return
    if i==len(T): sols.append(dict(tmap)); return
    t=T[i]; w=mems[i][pc] or '0'*16; o=op(w)
    p=cy[t+1]['ch25'];r=cy[t+1]['ch31']
    if p!=(o=='001') or r!=(o!='111'): return
    if not r:
      sols.append(dict(tmap)); return
    if o in kind:
      key=(pc,w)
      opts=[]
      if kind[o]=='c': opts.append(('n',(pc+1)%16))
      if key in tmap: opts.append(('t',tmap[key]))
      else: opts += [('new',x) for x in range(16)]
      for typ,n in opts:
        if typ=='new':
          tmap[key]=n; rec(i+1,n,tmap); del tmap[key]
        else: rec(i+1,n,tmap)
        if len(sols)>50: return
    else: rec(i+1,(pc+1)%16,tmap)
