import itertools
def rots():
  def none(a,c): return a,c
  def rlc(a,c): return ((a<<1)&255)|c, a>>7
  def rrc(a,c): return (a>>1)|(c<<7), a&1
  def rl(a,c): return ((a<<1)&255)|(a>>7), a>>7
  def rr(a,c): return (a>>1)|((a&1)<<7), a&1
  def shl(a,c): return (a<<1)&255, a>>7
  def shr(a,c): return a>>1, a&1
  def nott(a,c): return a^255,c
  return dict(none=none,rlc=rlc,rrc=rrc,rl=rl,rr=rr,shl=shl,shr=shr,not_=nott)
def alus():
  def add(a,k,c): r=a+k; return r&255, r>>8
  def adc(a,k,c): r=a+k+c; return r&255, r>>8
  def sub(a,k,c): r=a-k; return r&255, int(r<0)
  def sbc(a,k,c): r=a-k-c; return r&255, int(r<0)
  def rsb(a,k,c): r=k-a; return r&255, int(r<0)
  def rsc(a,k,c): r=k-a-c; return r&255, int(r<0)
  def xor(a,k,c): return a^k, c
  def and_(a,k,c): return a&k, c
  def or_(a,k,c): return a|k, c
  def nop(a,k,c): return a,c
  return dict(add=add,adc=adc,sub=sub,sbc=sbc,rsb=rsb,rsc=rsc,xor=xor,and_=and_,or_=or_,nop=nop)
R=rots();A=alus()
def search(v):
  res=[]
  for (rn,r),(an,al),(r2n,r2) in itertools.product(R.items(),A.items(),R.items()):
