      for c0 in (0,1):
        a,c=v[0],c0;ok=True
        for b in v[1:]:
          a,c=r(a,c); a,c=al(a,k,c); a,c=r2(a,c)
          if a!=b: ok=False;break
        if ok: res.append((rn,an,r2n,k,c0))
  return res
