import itertools
BIN={'add':lambda x,y:(x+y)&255,'sub':lambda x,y:(x-y)&255,'rsb':lambda x,y:(y-x)&255,'xor':lambda x,y:x^y,'and':lambda x,y:x&y,'or':lambda x,y:x|y,'movy':lambda x,y:y}
# an op: (dst in {A,R}, func, src2 in {A,R,k})  dst <- func(dst, src2)
OPS=[(d,f,s) for d in 'AR' for f in BIN for s in 'ARk' if not (s==d and f in ('movy',))]
def apply(st,opdef,k):
  d,f,s=opdef
  x=st[d]; y=st[s] if s!='k' else k
  st[d]=BIN[f](x,y)
def fit(seq, prog, A0=None, Rrange=range(256)):
  """prog: list of k values for ops; each iteration: A<-A0 (if not None) then ops; observe A"""
  sols=[]
  for defs in itertools.product(OPS,repeat=len(prog)):
    for R0 in Rrange:
      st={'A':A0,'R':R0};ok=True
      for v in seq:
        if A0 is not None: st['A']=A0
        for dfn,k in zip(defs,prog): apply(st,dfn,k)
        if st['A']!=v: ok=False;break
      if ok: sols.append((defs,R0))
  return sols
