import json
from tv import tv
from mem import resets, mem_at
from obs import X,Y,inp,sext5,TR
OPIDX={'000':0,'001':1,'010':2,'011':3,'100':4,'101':5,'110':6,'111':7}
def lowbyte(w):
  # w: 16-char DB-ordered word; op string = (ch14,ch20,ch22) -> b5,b6,b7
  from pcs import op,opr
  o=op(w); x=X(opr(w))
  return (int(o[0])<<5)|(int(o[1])<<6)|(int(o[2])<<7)|x
def evaluate(verbose=False):
  good=bad=0; badlist=[]
  lastrs=None; A=None
  for s,seq in TR:
    rs=max([x for x in resets if x<s] or [-1])
    if rs!=lastrs: A=0; lastrs=rs
    if not seq: A=None; continue
    for d in seq:
      o=d['op']; opr=d['opr']; t=d['t']
      if o=='001':
        v=tv(d['out'])
        if A is not None:
          if A==v: good+=1
          else: bad+=1; badlist.append((s,d['pc'],A,v))
        A=v
      elif o in ('101','111'): pass
      elif o=='000': A=X(opr)
      elif o=='100': A=None if A is None else (A+sext5(X(opr)))&255
      elif o=='110': A=inp(t)
      elif o=='010':
        w=mem_at(t)[X(opr)&15] or '0'*16; A=lowbyte(w)
      elif o=='011':
        w=mem_at(t)[X(opr)&15] or '0'*16; A=None if A is None else A^lowbyte(w)
  return good,bad,badlist
if __name__=='__main__':
  g,b,bl=evaluate(); print(g,b); print(bl)
