import json,sys
D=json.load(open('cyc.json')); cy=D['cyc']
ADDR=['ch29','ch24','ch05','ch12']
LOW=['ch03','ch30','ch19','ch23','ch02','ch14','ch20','ch22']   # bit0..bit7
PORT=['ch01','ch33','ch21','ch17','ch06','ch07','ch10','ch15']
OUTB=['ch08','ch00','ch32','ch28','ch27','ch04','ch13','ch18']
def val(r,chs): return sum(r[c]<<i for i,c in enumerate(chs))
class M:
  def __init__(s,opts): s.o=opts; s.reset(); s.mem=[0]*16
  def reset(s):
    s.run=0; s.pc=0; s.A=0; s.out=0; s.strobe=0; s.bubble=0; s.mem=[0]*16
  def step(s,r):
    o=s.o
    if r['ch26']:
      s.reset(); return
    strobe=0
    if not s.run:
      if r['ch11'] and (o.get('load_on_start',True) or not r['ch16']):
        s.mem[val(r,ADDR)]=val(r,LOW)
      if r['ch16']:
        s.run=1; s.pc=0; s.bubble=0
        if o.get('a_reset_on_start',True): s.A=0
    else:
      if s.bubble:
        s.bubble=0
      else:
        w=s.mem[s.pc]; op=w>>5; x=w&31
        npc=(s.pc+1)&15
        if op==0: s.A=x
        elif op==1: s.out=s.A; strobe=1
        elif op==2: s.A=s.mem[x&15]
        elif op==3: s.A^=s.mem[x&15]
        elif op==4: s.A=(s.A+(x-32 if x&16 else x))&255
        elif op==5:
          if s.A!=0: npc=x&15; s.bubble=1
        elif op==6: s.A=val(r,PORT)
        elif op==7: s.run=0
        s.pc=npc
    s.strobe=strobe
  def outputs(s):
    d={c:(s.out>>i)&1 for i,c in enumerate(OUTB)}
    d['ch25']=s.strobe; d['ch31']=s.run
    return d
def compare(opts,verbose=0):
  m=M(opts); started=False; errs=[]
  first=[k for k,r in enumerate(cy) if r['ch26']][0]
  for k in range(len(cy)-1):
    if k>=first+1:
      exp=m.outputs()
      for c,v in exp.items():
        if cy[k][c]!=v: errs.append((k,c,v,cy[k][c]))
    m.step(cy[k])
  return errs
if __name__=='__main__':
  e=compare({})
  print(len(e)); 
  import collections
  print(collections.Counter(x[0] for x in e).most_common(40))
